function chap(kind, file, title, description, keywords) {
	return {
		slug: `${kind}-dars-${file}`,
		kind,
		source: "book",
		file,
		title,
		description,
		keywords
	};
}
function own(kind, file, title, description, keywords) {
	return {
		slug: `${kind}-sual-${file}`,
		kind,
		source: "own",
		file,
		title,
		description,
		keywords
	};
}
