function isCourseHub(slug) {
	return Object.values(HUBS).some((hub) => hub.slug === slug);
}
function findCourse(slug) {
	return COURSE_PAGES.find((p) => p.slug === slug) ?? null;
}
function isCourseSlug(slug) {
	return isCourseHub(slug) || !!findCourse(slug);
}
function hubFor(slug) {
	return Object.keys(HUBS).find((kind) => HUBS[kind].slug === slug) ?? findCourse(slug)?.kind ?? null;
}
function pagesOf(kind) {
	return COURSE_PAGES.filter((p) => p.kind === kind);
}
